local function MapContainsVendor(currentMapID, vendorMapID)
    currentMapID = tonumber(currentMapID)
    vendorMapID = tonumber(vendorMapID)
    if not currentMapID or not vendorMapID then
        return false
    end
    if currentMapID == vendorMapID then
        return true
    end
    if not (C_Map and C_Map.GetMapInfo) then
        return false
    end
    local seen = {}
    local cursor = vendorMapID
    while cursor and not seen[cursor] do
        seen[cursor] = true
        local info = C_Map.GetMapInfo(cursor)
        cursor = info and info.parentMapID or nil
        if cursor == currentMapID then
            return true
        end
    end
    return false
end

function HousingVendorData:GetVendorList()
    return self.ReputationVendors or {}
end

function HousingVendorData:GetVendorsForMap(mapID, includeParents)
    local out = {}
    for _, vendor in ipairs(self.ReputationVendors or {}) do
        if vendor.mapID and ((includeParents and MapContainsVendor(mapID, vendor.mapID)) or vendor.mapID == mapID) then
            out[#out + 1] = vendor
        end
    end
    return out
end

function HousingVendorData:GetProfessionEntries()
    return self.ProfessionEntries or {}
end

function HousingVendorData:GetTrainerEntries()
    return self.TrainerEntries or {}
end

function HousingVendorData:GetMaterialsEntries()
    return self.MaterialEntries or {}
end

function HousingVendorData:GetReputationEntries()
    return self.ReputationEntries or {}
end

function HousingVendorData:GetPlanningEntries()
    local entries = {}
    for _, entry in ipairs(self.PlanningEntries or {}) do
        entries[#entries + 1] = entry
    end
    local wishCount = Villa.db and Villa.db.wishlist and Villa.db.wishlist.entries and (function(t) local n=0 for _ in pairs(t) do n=n+1 end return n end)(Villa.db.wishlist.entries) or 0
    entries[#entries + 1] = {
        key = "wishlist_crosscheck",
        title = "Wishlist Cross-Check",
        subtitle = tostring(wishCount) .. " tracked wishlist entries",
        detail = "Villa planning bridge for HousingVendor donor data. Use this surface to compare wishlisted decor against profession and reputation supply paths.",
        entryType = "planning",
        decorIds = { wishCount },
        owned = 0,
        total = wishCount,
    }
    return entries
end

function HousingVendorData:GetStatisticsEntries()
    return self.StatisticsEntries or {}
end

function HousingVendorData:GetPreviewEntries()
    return self.PreviewEntries or {}
end

function HousingVendorData:GetPreviewPosition(itemID)
    itemID = tonumber(itemID)
    if not itemID then return nil end
    return self.ModelPositions[itemID]
end

function HousingVendorData:GetMaterialInfo(itemID)
    itemID = tonumber(itemID)
    if not itemID then return nil end
    local sourceInfo = nil
    for _, info in ipairs(self.ReagentSources or {}) do
        if tonumber(info.itemID) == itemID then
            sourceInfo = info
            break
        end
    end
    if not sourceInfo then
        return nil
    end
    local priceInfo = nil
    for _, info in ipairs(self.VendorBasePrices or {}) do
        if tonumber(info.itemID) == itemID then
            priceInfo = info
            break
        end
    end
    return {
        name = sourceInfo.name,
        source = sourceInfo.source,
        price = priceInfo and priceInfo.price or nil,
    }
end

function HousingVendorData:IsHousingMaterial(itemID)
    return self:GetMaterialInfo(itemID) ~= nil
end


